using System.Globalization;
using System.Text;

namespace MNVTEngine;

/// <summary>
/// The version of this engine build: MAJOR.DDMM.PATCH.BUILD (see docs/architecture/versioning.md). The values come
/// from the build session (EngineVersion.g.cs, generated by MNVTEngine.Versioning); every engine assembly of the same
/// build carries the same version, and exported games embed it, so it needs no Git or repository at run time.
/// </summary>
public static partial class EngineVersion
{
    /// <summary>True for a development build (plain <c>dotnet build</c>), which has no build number (BUILD 0).</summary>
    public static bool IsDevelopmentBuild => Build == 0;

    /// <summary>The first 12 characters of <see cref="CommitHash"/>.</summary>
    public static string ShortCommit => CommitHash.Length > 12 ? CommitHash[..12] : CommitHash;

    /// <summary>"MNVTEngine 1.1411.140.4-dev (abcdef123456, dirty)": for window titles, logs and crash reports.</summary>
    public static string Summary => $"MNVTEngine {Version} ({ShortCommit}{(IsDirtyBuild ? ", dirty" : "")})";

    /// <summary>The human-readable block of <c>mnvt --version</c> and the editor's About window.</summary>
    public static string Describe()
    {
        var text = new StringBuilder().Append("MNVTEngine ").Append(Version).Append("\n\n");
        void Line(string name, string value) => text.Append(CultureInfo.InvariantCulture, $"{name + ":",-15}{value}\n");
        Line("Commit", IsDirtyBuild ? $"{ShortCommit} (modified working tree)" : ShortCommit);
        Line("Branch", Branch);
        Line("Build", IsDevelopmentBuild ? "0 (development build, no build number)" : Build.ToString(CultureInfo.InvariantCulture));
        Line("Build ID", BuildId);
        Line("Built", BuildTimestampUtc.ToString("yyyy-MM-dd HH:mm:ss 'UTC'", CultureInfo.InvariantCulture));
        Line("Configuration", BuildConfiguration);
        Line("Channel", Channel);
        Line("Dirty", IsDirtyBuild ? "true" : "false");
        if (SourceProblem is { } problem)
        {
            Line("Source", problem);
        }

        return text.ToString();
    }
}
